提示：n % 10 得到最后一位数字，n // 10 去掉最后一位。基准情形是 n == 0 时返回 0。递归情形是 sum_digits(n) = (n % 10) + sum_digits(n // 10)。完整代码：
def sum_digits(n):
    if n == 0:
        return 0
    return (n % 10) + sum_digits(n // 10)

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

# 前序：根→左→右（递归）
def preorder_recursive(root):
    if root is None:
        return []
    return [root.val] + preorder_recursive(root.left) + preorder_recursive(root.right)

# 前序：迭代（栈）
def preorder_iterative(root):
    if root is None:
        return []
    result, stack = [], [root]
    while stack:
        node = stack.pop()
        result.append(node.val)
        if node.right: stack.append(node.right)  # 先右后左，保证左先出
        if node.left: stack.append(node.left)
    return result

# 中序：左→根→右（递归）
def inorder_recursive(root):
    if root is None:
        return []
    return inorder_recursive(root.left) + [root.val] + inorder_recursive(root.right)

# 中序：迭代（栈，指针向左走到底）
def inorder_iterative(root):
    result, stack = [], []
    cur = root
    while cur or stack:
        while cur:           # 一直向左走到底
            stack.append(cur)
            cur = cur.left
        cur = stack.pop()    # 弹出栈顶（最左节点）
        result.append(cur.val)
        cur = cur.right      # 转向右子树
    return result

# 后序：左→右→根（递归）
def postorder_recursive(root):
    if root is None:
        return []
    return postorder_recursive(root.left) + postorder_recursive(root.right) + [root.val]

# 后序：迭代（巧用前序反转）
def postorder_iterative(root):
    if root is None:
        return []
    result, stack = [], [root]
    while stack:
        node = stack.pop()
        result.append(node.val)
        if node.left: stack.append(node.left)
        if node.right: stack.append(node.right)
    return result[::-1]  # 根→右→左 反转得 左→右→根

from collections import deque

def levelorder(root):
    """层序遍历：逐层从左到右访问所有节点"""
    if root is None:
        return []
    result, q = [], deque([root])
    while q:
        node = q.popleft()
        result.append(node.val)
        if node.left: q.append(node.left)
        if node.right: q.append(node.right)
    return result

def levelorder_by_level(root):
    """分层输出：[[第1层], [第2层], ...]"""
    if root is None:
        return []
    result, q = [], deque([root])
    while q:
        level = []
        for _ in range(len(q)):  # 关键：记录当前层大小
            node = q.popleft()
            level.append(node.val)
            if node.left: q.append(node.left)
            if node.right: q.append(node.right)
        result.append(level)
    return result

