def broken_qs(arr):
    if len(arr) <= 1:
        return arr
    pivot = arr[0]  # 固定选第一个
    left = [x for x in arr[1:] if x < pivot]
    right = [x for x in arr[1:] if x > pivot]
    return broken_qs(left) + [pivot] + broken_qs(right)
